"""Seven static references, built from the chapter briefs and local source assets.
No membership, messaging, search or lending backend is included.
"""
from pathlib import Path
from html import escape
import json,zipfile

def build_projects(root,site):
    meta=json.loads((root/'content/publication.json').read_text())
    chapters={c['project_slug']:c for c in json.loads((root/'content/chapters.json').read_text()) if c.get('project_slug')}
    css=(root/'assets/project-reference.css').read_text()
    js=(root/'assets/project-registration.js').read_text()
    code=chapters['registration']['code']
    form=code.split('<!-- registration:start -->',1)[1].split('<!-- registration:end -->',1)[0].strip()
    def doc(title,body,nav='',script=False):
        return f'<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="author" content="{escape(meta["author"])}"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{escape(title)} | HTML reference project</title><link rel="stylesheet" href="styles.css">'+('<script src="demo.js" defer></script>' if script else '')+f'</head><body><a class="skip" href="#main">Skip to main content</a><header><p><strong>NEIGHBOURHOOD LIBRARY</strong> / Fictional static reference</p>{nav}</header><main id="main" tabindex="-1">{body}</main><footer>© {meta["copyright_year"]} {escape(meta["author"])} / CTROTECH. Fictional teaching project, not a real service. Read the included assessment and solution notes before adapting it.</footer></body></html>'
    def nav(pages,current):
        return '<nav aria-label="Primary">'+''.join(f'<a href="{name}"'+(' aria-current="page"' if name==current else '')+'>'+escape(title)+'</a>' for name,title in pages.items())+'</nav>'
    sets={slug:{} for slug in chapters}
    sets['profile']['index.html']=doc('Volunteer profile','<h1>Ada, a fictional library volunteer</h1><p class="note">A made-up profile for practising HTML, not an author biography or real volunteer service.</p><p>In this exercise, Ada helps readers explore a small collection.</p><a href="#contact">Read the contact status</a><section><h2>Practice experience</h2><ul><li>Preparing a fictional reading-group notice.</li><li>Organising a sample shelf list.</li><li>Writing a catalogue entry as a learning task.</li></ul></section><section id="contact"><h2>Contact status</h2><p>No personal contact details or messaging service are supplied. Replace this status with your own verified route only when adapting the profile for real use.</p></section>')
    portfolio={'index.html':'Portfolio','project.html':'Notice-board note','reading-list.html':'Reading-list note'}
    bodies={
        'index.html':'<h1>A fictional front-end learning portfolio</h1><p>Two static studies in document structure, not commercial client work.</p><section><h2>Selected work</h2><article><h3>Library notice board</h3><p>A static notice-page structure study.</p><a href="project.html">Read the notice-board note</a></article><article><h3>Reading list</h3><p>A semantic list study, not a reservation service.</p><a href="reading-list.html">Read the reading-list note</a></article></section><section id="contact"><h2>Contact status</h2><p>No messages are collected and no personal contact route is supplied in this fictional portfolio.</p></section>',
        'project.html':'<h1>Library notice board</h1><p>This fictional project explores headings, lists and navigation. It claims no clients or measured results.</p><section><h2>Reference notice</h2><article><h3>Practice reading circle</h3><p>A made-up notice for a document-structure exercise, not an event invitation.</p></article></section><section><h2>Design decision</h2><p>The notice has its own subject and heading. It is not a button or a form.</p></section><a href="index.html#contact">Read the contact status</a>',
        'reading-list.html':'<h1>A reading-list structure study</h1><p>A fictional static list, not a reservation or account service.</p><section><h2>Supplied titles</h2><ul><li>Local histories</li><li>The walking notebook</li></ul></section><section><h2>Why a list?</h2><p>The items form one collection. A native list expresses that relationship without pretending it is a comparison table.</p></section><a href="index.html#contact">Read the contact status</a>'}
    for filename,body in bodies.items():sets['portfolio'][filename]=doc(portfolio[filename],body,nav(portfolio,filename))
    sets['registration']={'index.html':doc('Reading-group form','<h1>Reading-group form study</h1>'+form,script=True),'demo.js':js}
    sets['article']['index.html']=doc('How lending works','<article><h1>How lending works</h1><p class="note">Fictional practice policy, not instructions for a real library. Do not use it to decide a real loan or visit.</p><nav aria-label="On this page"><a href="#borrowing">Borrowing</a><a href="#renewal">Renewal</a><a href="#returns">Returns</a></nav><section id="borrowing"><h2>Borrowing</h2><p>In this fictional model, a loan lasts 14 calendar days after its start date. A practice loan starting 1 October 2026 is due 15 October 2026.</p></section><section id="renewal"><h2>Renewal</h2><p>One eligible renewal before the due date adds 14 calendar days to that due date. A sample 15 October due date would move to 29 October. This page cannot check eligibility or perform a renewal.</p></section><section id="returns"><h2>Returns</h2><p>For the exercise, mark the practice item as returned in a local paper log. This page records no real return and supplies no real branch address.</p></section><footer><p>Practice guide reviewed <time datetime="2026-10-15">15 October 2026</time>.</p></footer></article>')
    rows=''.join(f'<tr><th scope="row">{collection}</th><td>{count}</td><td>October 2026</td></tr>' for collection,count in [('Fiction',42),('Local history',18),('Reference',9)])
    sets['dashboard']['index.html']=doc('Lending dashboard','<h1>Lending dashboard</h1><p class="note">Fictional static data for October 2026. Counts mean loan entries, not unique readers or available stock. There is no live feed.</p><section><h2>Sample loans</h2><dl class="metrics"><div><dt>Total across these three collections</dt><dd>69 loans</dd></div><div><dt>Collections represented</dt><dd>3 collections</dd></div></dl><p>The total is 42 + 18 + 9, not a percentage or a change from a previous period.</p><div class="tablewrap" tabindex="0" role="region" aria-label="Scrollable sample lending table"><table><caption>Fictional loans by collection, October 2026</caption><thead><tr><th scope="col">Collection</th><th scope="col">Loans (count)</th><th scope="col">Period</th></tr></thead><tbody>'+rows+'</tbody></table></div></section>')
    shapes=''
    for row in range(3):
        for col in range(6):shapes+=f'<rect x="{75+col*82}" y="{55+row*110}" width="54" height="68" rx="2" fill="{["#234d42","#a74125","#8f9e74"][col%3]}"/>'
        shapes+=f'<path d="M55 {130+row*110} H585" stroke="#314739" stroke-width="8"/>'
    art=[('shelves','Three shelf rows, each holding six book shapes','Organising a small collection.',shapes),('window','A rectangular window divided into six panes','Light in a reading space.','<rect x="140" y="45" width="360" height="310" fill="#c4d8cc" stroke="#234d42" stroke-width="12"/><path d="M260 45 V355 M380 45 V355 M140 200 H500" stroke="#234d42" stroke-width="10"/>'),('tables','Two reading tables seen from above, each with a book shape','A study in shared space.','<rect x="90" y="100" width="190" height="200" rx="12" fill="#b78958"/><rect x="360" y="100" width="190" height="200" rx="12" fill="#b78958"/><rect x="130" y="150" width="70" height="90" fill="#234d42"/><rect x="405" y="160" width="70" height="90" fill="#a74125"/>')]
    gallery='<h1>Library illustration gallery</h1><p>Three local drawings, not photographs of a real venue.</p><ul class="gallery">'
    for name,alt,caption,shape in art:
        loading='eager' if name=='shelves' else 'lazy'
        gallery+=f'<li><figure><img src="{name}.svg" alt="{alt}" width="640" height="400" loading="{loading}" decoding="async"><figcaption>{caption}</figcaption></figure></li>'
        sets['gallery'][name+'.svg']=f'<svg xmlns="http://www.w3.org/2000/svg" width="640" height="400" viewBox="0 0 640 400"><rect width="640" height="400" fill="#eee9d9"/>{shape}</svg>'
    sets['gallery']['index.html']=doc('Illustration gallery',gallery+'</ul>')
    pages={
      'index.html':('Home','<h1>Neighbourhood Library</h1><p>A static reference site for learning HTML.</p><p class="note">No books can be reserved and no applications are collected here.</p><section><h2>Explore the example</h2><ul><li><a href="catalogue.html">Browse fictional book data</a></li><li><a href="membership.html">Inspect the demonstration form</a></li><li><a href="visit.html">Read the fictional visit information</a></li></ul></section>'),
      'catalogue.html':('Catalogue','<h1>Example catalogue</h1><p>Fictional titles for a static exercise. Nothing can be reserved.</p><div class="tablewrap" tabindex="0" role="region" aria-label="Scrollable fictional catalogue"><table><caption>Example catalogue entries</caption><thead><tr><th scope="col">Title</th><th scope="col">Collection</th></tr></thead><tbody><tr><th scope="row">Local histories</th><td>Community</td></tr><tr><th scope="row">The walking notebook</th><td>Travel</td></tr><tr><th scope="row">Small gardens</th><td>Practical guides</td></tr></tbody></table></div>'),
      'membership.html':('Membership','<h1>Membership interface study</h1>'+form),
      'visit.html':('Visit','<h1>Plan a fictional visit</h1><p class="note">This project is not a real destination. Do not travel based on these example details.</p><section><h2>Practice opening hours</h2><dl><dt>Tuesday to Saturday</dt><dd>09:00 to 17:00</dd><dt>Sunday and Monday</dt><dd>Closed in this practice model</dd></dl></section><section id="access"><h2>Access information</h2><p>No entrance, step-free route, parking or facilities have been verified. A real service must check relevant details before publishing access claims.</p></section><section><h2>Location and contact status</h2><p>No real street address or contact route is supplied. These practice hours are not a live timetable.</p></section>')}
    titles={name:title for name,(title,_) in pages.items()}
    for filename,(title,body) in pages.items():sets['capstone'][filename]=doc(title,body,nav(titles,filename),filename=='membership.html')
    sets['capstone']['demo.js']=js
    for slug,files in sets.items():
        folder=site/'projects'/slug;folder.mkdir(parents=True,exist_ok=True)
        chapter=chapters[slug];files['styles.css']=css
        files['README.md']=f'# {chapter["title"]}\n\nBy {meta["author"]} | CTROTECH\n\nA fictional static teaching implementation, not a real service. Open index.html for the offline documents, or serve this folder locally for request inspection. All styles, images and scripts are local. Never enter real personal data.\n\nRead BRIEF.md before comparing with SOLUTION.md. These notes are generated from the same maintained chapter source used by the website and PDF.\n\nForms begin disabled. Successful script setup installs its local handlers before enabling fields. Failed/disabled scripting leaves instructions and disabled fields, not a collection fallback. Browser autofill/history policy is separate from this demonstration not storing an application. There is no membership, reservation, messaging or search backend.\n\n{meta['copyright_notice']}\n{meta['reuse_license']}\n\n## Files\n'+'\n'.join('- '+name for name in sorted([*files,'README.md','BRIEF.md','SOLUTION.md']))+'\n'
        files['BRIEF.md']=f'# Chapter {chapter["number"]}: {chapter["title"]}\n\n## Objectives\n\n'+'\n'.join('- '+o for o in chapter['objectives'])+'\n\n'+chapter['lesson']+'\n\n## Exercise\n\n'+chapter['question']+'\n'
        files['SOLUTION.md']=f'# Reference reasoning: {chapter["title"]}\n\n'+chapter['explanation']+'\n\n## Explained exercise answer\n\n'+chapter['answer']+'\n\n## Sources\n\n'+'\n'.join('- '+x['title']+': '+x['url'] for x in chapter['sources'])+'\n\nSame-assistant reference reasoning, not an independent assessment or certification. Record actual observations against BRIEF.md; do not award points for unperformed checks.\n'
        for name,content in files.items():(folder/name).write_text(content)
        with zipfile.ZipFile(site/'downloads'/f'project-{slug}.zip','w',zipfile.ZIP_DEFLATED) as z:
            for p in sorted(folder.iterdir()):z.write(p,slug+'/'+p.name)
